"""Cuenta del gasto en USD de DeepSeek y Big Pickle, con tope mensual.

Sin IA: solo sumas y lectura de archivos. El tope es 5 USD al mes (acuerdo A-27).
"""

import json
import os
from datetime import datetime


# Tope de gasto mensual en USD (acuerdo A-27).
TOPE_MES_USD = 5.0

# Precios por millon de tokens, en hora PICO (los mas caros, para que el tope
# se equivoque del lado seguro).
# Copiados de api-docs.deepseek.com/quick_start/pricing el 2026-09-19.
PRECIOS_POR_MILLON = {
    'flash': {'acierto': 0.006, 'fallo': 0.30, 'salida': 1.20},
    'pro': {'acierto': 0.044, 'fallo': 1.32, 'salida': 3.96},
}


def ruta():
    """Devuelve la ruta del archivo de gasto en USD.

    Si existe la variable de entorno INGENIERO_GASTO_USD_TEST, se usa esa.
    Si no, se usa memoria/GASTO_USD.jsonl junto a la carpeta cuerpo.
    """
    prueba = os.environ.get('INGENIERO_GASTO_USD_TEST')
    if prueba:
        return prueba
    aqui = os.path.dirname(os.path.abspath(__file__))
    raiz = os.path.dirname(aqui)
    return os.path.join(raiz, 'memoria', 'GASTO_USD.jsonl')


def _ruta_log_bigpickle():
    """Devuelve la ruta del log de Big Pickle."""
    prueba = os.environ.get('INGENIERO_BIGPICKLE_LOG_TEST')
    if prueba:
        return prueba
    aqui = os.path.dirname(os.path.abspath(__file__))
    raiz = os.path.dirname(aqui)
    return os.path.join(raiz, 'memoria', 'BIGPICKLE.log')


def _a_entero(valor):
    """Convierte a entero lo que se pueda; si no, devuelve 0."""
    try:
        if valor is None:
            return 0
        return int(valor)
    except (TypeError, ValueError):
        return 0


def costo_deepseek(modelo, uso):
    """Devuelve el costo en USD de una respuesta de DeepSeek.

    modelo: nombre del modelo (si lleva 'flash' se usa la tabla flash, si no la pro).
    uso: el dict 'usage' de la respuesta de DeepSeek.
    """
    if not isinstance(uso, dict):
        uso = {}

    nombre = str(modelo or '').lower()
    if 'flash' in nombre:
        tabla = PRECIOS_POR_MILLON['flash']
    else:
        tabla = PRECIOS_POR_MILLON['pro']

    acierto = _a_entero(uso.get('prompt_cache_hit_tokens'))
    fallo = _a_entero(uso.get('prompt_cache_miss_tokens'))
    salida = _a_entero(uso.get('completion_tokens'))

    # Si no vienen los tokens de cache, se usa prompt_tokens como fallo.
    if acierto == 0 and fallo == 0:
        fallo = _a_entero(uso.get('prompt_tokens'))

    usd = (
        acierto * tabla['acierto']
        + fallo * tabla['fallo']
        + salida * tabla['salida']
    ) / 1000000.0
    return usd


def anotar(quien, modelo, uso):
    """Agrega una linea json con el gasto al archivo de ruta(). Nunca lanza."""
    try:
        usd = costo_deepseek(modelo, uso)
        linea = {
            'cuando': datetime.now().isoformat(),
            'quien': quien,
            'modelo': modelo,
            'uso': uso,
            'usd': usd,
        }
        destino = ruta()
        carpeta = os.path.dirname(destino)
        if carpeta and not os.path.isdir(carpeta):
            os.makedirs(carpeta, exist_ok=True)
        with open(destino, 'a', encoding='utf-8') as f:
            f.write(json.dumps(linea, ensure_ascii=False) + '\n')
    except Exception:
        pass


def _mes_de(hoy):
    """Devuelve 'AAAA-MM' del dia dado (o de hoy si no se da)."""
    if hoy is None:
        momento = datetime.now()
    elif isinstance(hoy, datetime):
        momento = hoy
    else:
        momento = datetime.fromisoformat(str(hoy))
    return momento.strftime('%Y-%m')


def _sumar_jsonl(mes):
    """Suma los 'usd' de las lineas del mes en el archivo de ruta()."""
    total = 0.0
    try:
        destino = ruta()
        if not os.path.isfile(destino):
            return 0.0
        with open(destino, 'r', encoding='utf-8') as f:
            for linea in f:
                linea = linea.strip()
                if not linea:
                    continue
                try:
                    dato = json.loads(linea)
                except Exception:
                    continue
                cuando = str(dato.get('cuando', ''))
                if not cuando.startswith(mes):
                    continue
                try:
                    total += float(dato.get('usd', 0.0))
                except (TypeError, ValueError):
                    continue
    except Exception:
        return total
    return total


def _sumar_bigpickle(mes):
    """Suma los costo= del log de Big Pickle para el mes dado."""
    total = 0.0
    try:
        destino = _ruta_log_bigpickle()
        if not os.path.isfile(destino):
            return 0.0
        with open(destino, 'r', encoding='utf-8', errors='replace') as f:
            for linea in f:
                linea = linea.rstrip('\n')
                if not linea:
                    continue
                if not linea.startswith(mes):
                    continue
                partes = linea.split('\t')
                for parte in partes:
                    parte = parte.strip()
                    if parte.startswith('costo='):
                        valor = parte[len('costo='):].strip()
                        try:
                            total += float(valor)
                        except (TypeError, ValueError):
                            pass
                        break
    except Exception:
        return total
    return total


def gastado_del_mes(hoy=None):
    """Suma lo gastado este mes: DeepSeek (jsonl) mas Big Pickle (log). Nunca lanza."""
    try:
        mes = _mes_de(hoy)
    except Exception:
        return 0.0
    total = 0.0
    total += _sumar_jsonl(mes)
    total += _sumar_bigpickle(mes)
    return total


def se_paso_del_tope(hoy=None):
    """Devuelve True si lo gastado este mes llega o pasa el tope."""
    try:
        return gastado_del_mes(hoy) >= TOPE_MES_USD
    except Exception:
        return False
